const fs = require("node:fs");
const {DatabaseSync} = require("node:sqlite");
const {Transpiler} = require("@abaplint/transpiler");
const assert = require("node:assert/strict");

async function execute() {
    const sourceFiles = [process.argv[2], "t000.tabl.xml"].map(filename => ({
        filename,
        contents: fs.readFileSync(filename, "utf8")
    }));
    const output = await new Transpiler().runRaw(sourceFiles);
    const queries = output.databaseSetup.schemas.sqlite;
    const db = new DatabaseSync(":memory:");
    for (const entry of queries) {
        console.error(entry.trim());
        db.exec(entry);
    }
    assert.equal(db.prepare("SELECT count(*) FROM zi_hello_world").get()["count(*)"], 0);
    db.prepare("INSERT INTO t000 (mandt) VALUES (?)").run("123");
    const result = db.prepare("SELECT client, greeting FROM zi_hello_world").get();
    assert.equal(result.client, "123");
    assert.equal(result.greeting, "Hello, World!");
    console.log(result.greeting);
}
execute().catch(error => { console.error(error); process.exitCode = 1; });

