const fs = require("node:fs");
const path = require("node:path");
const assert = require("node:assert/strict");

const main = require.resolve("@abaplint/transpiler");
const source = path.join(path.dirname(main), "db", "cds_database_view.js");
let body = fs.readFileSync(source, "utf8");
const field = "const field = node.findDirectExpression(cds.CDSPrefixedName);";
assert.equal(body.split(field).length, 2);
body = body.replace(field, field + "\n        const literal = node.findDirectExpression(cds.CDSString);");
const condition = "child === field || child === as";
assert.equal(body.split(condition).length, 2);
body = body.replace(condition, "child === field || child === literal || child === as");
const missing = 'if (field === undefined) {';
assert.equal(body.split(missing).length, 2);
body = body.replace(missing, 'if (literal) {\n            const alias = as?.findDirectExpression(cds.CDSName);\n            if (!alias) return this.unsupported("string projection requires an alias");\n            return this.expression(literal) + " AS " + this.quote(this.name(alias));\n        }\n        ' + missing);
fs.writeFileSync(source, body);
